//
// What the offline queue survives, and what loses it. Two fields per store and the difference
// between them matters: survives/lostTo are what is true of the store, and says is what a screen
// renders. A store whose behaviour is wider than what it says is a screen with a gap in it.
//
// Nothing here is encrypted by MyThuso and nothing here is sent anywhere. Fictional readings.

import Foundation

enum CaptureData {
    /// Something that can happen to a phone or a tab, named once so two platforms cannot call the
    /// same event by two names and then disagree about it without anybody noticing.
    struct DurabilityEvent: Identifiable, Hashable { let id: String; let name: String }
    /// One place work waits. `survives` and `lostTo` are behaviour; `saysSurvives` and
    /// `saysLostTo` are the sentences a screen renders, and they are deliberately separate fields.
    struct Store: Identifiable, Hashable {
        let id: String
        let platform: String
        /// "file" or "memory". A memory store is one that says out loud that it keeps nothing.
        let kind: String
        let heldIn: String
        let survives: [String]
        let lostTo: [String]
        let saysSurvives: [String]
        let saysLostTo: [String]
    }
    /// What is still true after the disk has refused the work. Named once, so that two platforms
    /// cannot promise the same thing in words a check cannot compare.
    struct WriteOutcome: Identifiable, Hashable { let id: String; let name: String }
    /// A way the disk refuses. `leaves` is behaviour, in outcome ids; `says` is the one sentence
    /// a screen renders; `saidBy` is which stores render it today, and it is deliberately not
    /// every store that can suffer it.
    struct WriteFailure: Identifiable, Hashable {
        let id: String
        let name: String
        let detectedBy: String
        let leaves: [String]
        let says: String
        let saidBy: [String]
    }

    // What the offline queue survives, and what loses it — as data, per platform, because it was
    // prose twice about the same disk. Android's FileBook carried three sentences about a JSON file
    // in the app's private storage; iOS's CaptureQueueView and VisitQueueView carried six about a
    // JSON file in Application Support; the web's queue screen carried one about a module-level
    // array. A nurse reading the Android sentence and the iOS list would not have known they
    // describe one behaviour, and nothing in this repository compared them. This section is that
    // comparison. It does not flatten three platforms into one sentence: the web genuinely keeps
    // less, because scripts/check-boundaries.mjs forbids the browser's local storage, session
    // storage and IndexedDB across apps/web/src and a preview must not leave a patient's readings on
    // a borrowed machine. What it does is make the promise one promise and the differences visible.
    static let durabilityEvents: [DurabilityEvent] = [
        .init(id: "navigation", name: "Moving between screens"),
        .init(id: "reload", name: "Reloading the page or closing the tab"),
        .init(id: "close-app", name: "Closing the app"),
        .init(id: "crash", name: "A crash, a force-quit, or the process being killed"),
        .init(id: "restart", name: "Restarting the phone"),
        .init(id: "sign-out", name: "Signing out"),
        .init(id: "delete", name: "Deleting the app"),
        .init(id: "clear-storage", name: "Clearing the app's storage from the operating system's settings"),
        .init(id: "factory-reset", name: "A factory reset"),
        .init(id: "lost-phone", name: "Losing the phone"),
        .init(id: "second-device", name: "Picking up a second device")
    ]
    static func durabilityEvent(_ id: String) -> DurabilityEvent? { durabilityEvents.first { $0.id == id } }

    static let stores: [Store] = [
        .init(id: "web-in-memory", platform: "web", kind: "memory",
              heldIn: "A module-level array in the tab that is open. Nothing is written to the browser's storage, because nothing in apps/web/src may write to it.",
              survives: ["navigation"],
              lostTo: ["reload", "crash", "restart", "sign-out", "delete", "clear-storage", "factory-reset", "lost-phone", "second-device"],
              saysSurvives: [],
              saysLostTo: [
                  "Closing this tab loses it. Nothing in this app may leave a patient’s readings on the machine it was opened on."]),
        .init(id: "ios-capture-ledger", platform: "ios", kind: "file",
              heldIn: "A JSON file in Application Support, written through FileManager with iOS data protection on it, and kept out of device backups.",
              survives: ["close-app", "crash", "restart", "sign-out"],
              lostTo: ["delete", "lost-phone", "second-device"],
              saysSurvives: [
                  "A crash or a force-quit. Every entry is written at the moment it is taken, not when the app closes.",
                  "A restart of the phone.",
                  "A sign-out. This preview’s sign-out returns to the first-run flow and never touches the file — the entries belong to the work, not to the session."],
              saysLostTo: [
                  "Deleting the app. iOS removes the file with it, and nothing here can prevent that.",
                  "Losing the phone. The file is deliberately kept out of device backups, because a queue of readings is special personal information and syncing it into somebody’s laptop backup is a disclosure nobody consented to. The answer to a lost phone is to send, not to back up.",
                  "A second device. Nothing is shared between phones; there is no server in this build to share it through."]),
        .init(id: "ios-visit-queue", platform: "ios", kind: "file",
              heldIn: "The whole visit, in a file on this phone — not only the readings.",
              survives: ["close-app", "crash", "restart", "sign-out"],
              lostTo: ["delete", "lost-phone", "second-device"],
              saysSurvives: [
                  "A crash or a force-quit. Each piece is written the moment it is finished, not when the app closes.",
                  "A restart of the phone.",
                  "A sign-out. This preview’s sign-out returns to the first-run flow and never touches the file — the work belongs to the visit, not to the session."],
              saysLostTo: [
                  "Deleting the app. iOS removes the file with it, and nothing here can prevent that.",
                  "Losing the phone. The file is deliberately kept out of device backups: a consent, seven readings and a signature are special personal information, and syncing them into somebody’s laptop backup is a disclosure nobody consented to. The answer to a lost phone is to send, not to back up.",
                  "A second device. Nothing is shared between phones; there is no server in this build to share it through."]),
        .init(id: "android-private-file", platform: "android", kind: "file",
              heldIn: "A file in this app’s own private storage on this phone. Nothing is sent anywhere: the app declares no permissions at all, internet included.",
              survives: ["close-app", "crash", "restart", "sign-out"],
              lostTo: ["delete", "clear-storage", "factory-reset", "lost-phone", "second-device"],
              saysSurvives: [
                  "Closing the app, the process being killed, a crash, restarting the phone, and signing out."],
              saysLostTo: [
                  "Uninstalling MyThuso, clearing the app’s storage in Android settings, or a factory reset. It is never backed up off this phone — the manifest sets allowBackup to false."]),
        .init(id: "android-in-memory", platform: "android", kind: "memory",
              heldIn: "Held in memory only, because this screen was opened without a file store.",
              survives: [],
              lostTo: ["navigation", "reload", "close-app", "crash", "restart", "sign-out", "delete", "clear-storage", "factory-reset", "lost-phone", "second-device"],
              saysSurvives: [
                  "Nothing. Every entry here is lost when this screen closes."],
              saysLostTo: [
                  "A crash, a restart, a sign-out, or leaving this screen."])
    ]
    /// The stores this platform actually has. A screen asks for its own and never renders another
    /// platform's promise, which is how three sets of sentences became one contract in the first
    /// place.
    static func stores(on platform: String) -> [Store] { stores.filter { $0.platform == platform } }
    static func store(_ id: String) -> Store? { stores.first { $0.id == id } }

    // The same separation the stores above use, and it is the point of both. `leaves` is what is
    // true after the failure, in outcome ids — behaviour, comparable between failures and checkable
    // across platforms. `says` is the one sentence a screen renders, word for word. `saidBy` is
    // which stores render it today, and it is deliberately not every store that can suffer the
    // failure: a memory store cannot be refused by a disk, so it is never on the list. iOS's two
    // file queues could run a phone out of room exactly as Android's could and said nothing in these
    // words until 1 October 2026, when both began answering a refused write with the same two
    // sentences through CaptureData.writeFailure — the gap this field was left to show is closed,
    // and the field stays so that the next store to fall silent shows up the same way.
    static let writeOutcomes: [WriteOutcome] = [
        .init(id: "held-in-memory", name: "The work is still in memory and still on the screen"),
        .init(id: "not-on-disk", name: "The work is not on the disk, so closing the app now loses it"),
        .init(id: "earlier-writes-intact", name: "Whatever was written down before this is untouched"),
        .init(id: "nothing-deleted", name: "Nothing is deleted or overwritten to get past it"),
        .init(id: "person-can-clear-it", name: "The person holding the phone can do something that clears it"),
        .init(id: "renamed-aside", name: "The file that would not read back is renamed aside and kept"),
        .init(id: "new-name-on-screen", name: "What that file is now called is on the screen")
    ]
    static func writeOutcome(_ id: String) -> WriteOutcome? { writeOutcomes.first { $0.id == id } }

    static let writeFailures: [WriteFailure] = [
        .init(id: "disk-full", name: "The phone has no room left",
              detectedBy: "The write threw, and the failure or one of the causes behind it named ENOSPC or said there was no space left on the device.",
              leaves: ["held-in-memory", "not-on-disk", "earlier-writes-intact", "nothing-deleted", "person-can-clear-it"],
              says: "This phone has no room left, so what you have just done could not be written down. It is still on the screen and it is still yours, but it is not on the disk: if the app closes now, it is gone. Free some space on the phone and it will be written again.",
              saidBy: ["android-private-file", "ios-capture-ledger", "ios-visit-queue"]),
        .init(id: "write-refused", name: "The disk would not take it, and did not say why",
              detectedBy: "The write threw for any other reason.",
              leaves: ["held-in-memory", "not-on-disk", "earlier-writes-intact", "nothing-deleted"],
              says: "This phone would not take the write, and it did not say why. What you have just done is still on the screen and still yours, but it is not on the disk: if the app closes now, it is gone. Nothing that was already written down has been touched.",
              saidBy: ["android-private-file", "ios-capture-ledger", "ios-visit-queue"]),
        .init(id: "will-not-parse", name: "What is on the disk will not read back",
              detectedBy: "The file exists and the parser would not take it. It is renamed aside before anything else is written to that name.",
              leaves: ["nothing-deleted", "renamed-aside", "new-name-on-screen"],
              says: "A file that will not parse is kept, not deleted. Losing work to a bad parse is still losing work.",
              saidBy: [])
    ]
    static func writeFailure(_ id: String) -> WriteFailure? { writeFailures.first { $0.id == id } }
    /// The refusals a given store's screen renders today. A store with none of them is not a store
    /// that cannot fail; it is a screen that has nothing to say when it does.
    static func writeFailures(saidBy store: String) -> [WriteFailure] { writeFailures.filter { $0.saidBy.contains(store) } }

    /// The sibling of queuedIsNotLost: never dropped to make a sync succeed has to mean never dropped to make a parse succeed either. The unreadable file is renamed aside and the screen says what it is now called, because a screen that says work was kept and cannot say where it was kept has asked to be believed rather than checked.
    static let quarantinedFile = "A file that will not parse is kept, not deleted. Losing work to a bad parse is still losing work."
    /// Real readings would need the controls in docs/PRIVACY-AND-SECURITY.md first. Said on the screen rather than implied by silence, because a queue that looks durable looks secure, and those are not the same claim.
    static let notEncrypted = "None of this is encrypted by MyThuso. It is a design preview holding fictional readings in a file the operating system keeps private to the app, and no more than that."
}
